-- Skill progression (#37 stage 6). How a skill rose was code (the kill rules, Parry and Block, the
-- arrow, cast and book gains) or the gather.json `skillGain` rows; it is now content. Each skill row
-- in classes.json may carry a `progression` (a model, `chance` or `xp`, and settings by source:
-- kill, shot, defend, cast, gather, craft, hit), over the world defaults in classes.json
-- `progression` (with the line every gain prints, the stat tables formulas read and the XP curves).
-- `gather.json` `skillGain` and the unread `gathering.texts.advanced` go; spell schools lose their
-- own `line` and skill books their `shown` (one line for every skill), and skill books gain their
-- teaching (1.6's: 1 + random(5), up to 77). A kill rolls the weapon's skills in its list order, so
-- the lists are put in 1.6's roll order.
--
-- `character_skills` gains `xp`, each skill's running XP total for the `xp` model (0 for all).
--
-- The old rules are worked out at each layer as stage 5 did: the packs (the last imported pack with
-- each section, over Classic), then the operator's rows, then the draft. Imported packs' skills take
-- the progression the packs' gain rows and skill bindings imply, and their classes the world
-- defaults; the operator layer gets a skill row wherever its gain rows or bindings come out
-- differently (and its own skill rows take the progression of its layer); the draft likewise over
-- the operator layer. The rows the publish log keeps for undo take the same changes, with skills'
-- progression from the operator layer; the old `skillGain` rows leave it, so undoing a publish that
-- changed a gain chance no longer puts that chance back.
-- A skill an older weapon list names that 1.6 never rolled on a kill (only its twelve kill skills
-- rose) gets `kill: false`, so it still never rises from kills (Classic names none).
--
-- Generated by a script from the Classic content at the time; the literals are Classic's old skill
-- rows, gain rows and bindings, and its new progression.

ALTER TABLE character_skills ADD COLUMN xp INTEGER NOT NULL DEFAULT 0;

CREATE TEMP TABLE classic_65 (skills TEXT, gains TEXT, binds TEXT, prog TEXT);
INSERT INTO classic_65 VALUES ('[{"skill":"Slash"},{"skill":"Thrust"},{"skill":"Parry"},{"skill":"HeavyArms","display":"Heavy Arms"},{"skill":"AxeFighting","display":"Axe Fighting"},{"skill":"Swordsmanship"},{"skill":"Fencing"},{"skill":"Magery"},{"skill":"BlackArts","display":"Black Arts"},{"skill":"UnholyCombat","display":"Unholy Combat"},{"skill":"Archery"},{"skill":"Meditation","hidden":true},{"skill":"Blessing"},{"skill":"Sorcery"},{"skill":"Musicianship"},{"skill":"TerrainNavigating","display":"Terrain Navigating","hidden":true},{"skill":"StaffFighting","display":"Staff Fighting"},{"skill":"ItemIdentification","display":"Item Identification","hidden":true},{"skill":"Illusion"},{"skill":"HammerWielding","display":"Hammer Wielding"},{"skill":"fire","display":"Fire"},{"skill":"Water"},{"skill":"wind","display":"Wind"},{"skill":"Earth"},{"skill":"Block"},{"skill":"MartialArts","display":"Martial Arts"},{"skill":"Wizardry"},{"skill":"Wrath"},{"skill":"Punch"},{"skill":"Cooking"},{"skill":"Alchemy"},{"skill":"Lumberjacking"},{"skill":"Carpentry"},{"skill":"Fishing"},{"skill":"Blacksmithing"},{"skill":"Mining"},{"skill":"Shoveling"},{"skill":"Farming"}]', '[{"handler":"LumberjackImp","skill":"Lumberjacking","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Lumberjacking!"},{"handler":"ShovelingImp","skill":"Shoveling","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Shoveling!"},{"handler":"FarmingImp","skill":"Farming","chance":12,"min":0,"below":100,"text":"You have advanced in the art of Farming!"},{"handler":"MiningImp","skill":"Mining","chance":22,"min":0,"below":100,"text":"You have advanced in the art of Mining!"},{"handler":"FishingImp","skill":"Fishing","chance":16,"min":0,"below":100,"text":"You have advanced in the art of Fishing!"},{"handler":"CookImp","skill":"Cooking","chance":8,"min":0,"below":100,"text":"You have advanced in the art of Cooking!"},{"handler":"SmithImp","skill":"Blacksmithing","chance":9,"min":0,"below":100,"text":"You have advanced in the art of Blacksmithing!"},{"handler":"AlchemyImp","skill":"Alchemy","chance":15,"min":0,"below":100,"text":"You have advanced in the art of Alchemy!"},{"handler":"CarpentryImp","skill":"Carpentry","chance":9,"min":0,"below":100,"text":"You have advanced in the art of Carpentry!"}]', '{"parry":"Parry","block":"Block","archery":"Archery","martialArts":"MartialArts","staffFighting":"StaffFighting","magery":"Magery","fishing":"Fishing","blacksmithing":"Blacksmithing","cooking":"Cooking","alchemy":"Alchemy","carpentry":"Carpentry"}', '{"line":"You have advanced in the art of {skill}!","tables":{"wisdomBonus":{"stat":"wisdom","start":30,"tiers":[{"above":5,"add":-5},{"above":10,"add":-7},{"above":15,"add":-8},{"above":20,"add":-5},{"above":22,"add":-2},{"above":23,"add":-3}]}},"curves":{},"defaults":{"chance":{"kill":{"roll":[{"op":"set","value":"skill"},{"op":"add","value":"wisdomBonus"}],"cap":"faction","monsterCap":true},"shot":{"roll":[{"op":"set","value":"skill"}],"cap":100},"defend":{"roll":[{"op":"set","value":"skill"}],"cap":100},"cast":{"roll":[{"op":"set","value":"skill"}],"cap":"mage"}},"xp":{}}}');
CREATE TEMP TABLE kill_65 (k TEXT PRIMARY KEY, s TEXT NOT NULL);
INSERT INTO kill_65 VALUES ('thrust', '{"roll":[{"op":"set","value":"skill"},{"op":"add","value":40},{"op":"subtract","value":"stamina"},{"op":"add","value":"wisdomBonus"}],"requires":{"skill":"Slash","above":30}}'), ('heavyarms', '{"requires":{"skill":"Thrust","above":60}}'), ('swordsmanship', '{"roll":[{"op":"set","value":"skill"},{"op":"add","value":25},{"op":"subtract","value":"stamina"},{"op":"add","value":"wisdomBonus"}],"requires":{"skill":"Slash","above":50}}'), ('fencing', '{"roll":[{"op":"set","value":"skill"},{"op":"add","value":25},{"op":"subtract","value":"stamina"},{"op":"add","value":"wisdomBonus"}],"requires":{"skill":"Swordsmanship","above":20}}'), ('unholycombat', '{"roll":[{"op":"set","value":"skill"}],"cap":"mage"}'), ('stafffighting', '{"cap":"mage"}'), ('hammerwielding', '{"roll":[{"op":"set","value":"skill"},{"op":"add","value":40},{"op":"subtract","value":"stamina"},{"op":"add","value":"wisdomBonus"}]}');
CREATE TEMP TABLE rules_65 (k TEXT PRIMARY KEY, n INTEGER NOT NULL);
INSERT INTO rules_65 VALUES ('hammerwielding', 0), ('axefighting', 1), ('punch', 2), ('archery', 3), ('martialarts', 4), ('unholycombat', 5), ('thrust', 6), ('stafffighting', 7), ('slash', 8), ('heavyarms', 9), ('swordsmanship', 10), ('fencing', 11);

-- Every skill a weapon's kill list names, in any layer.
CREATE TEMP TABLE weap_65 (k TEXT PRIMARY KEY);
INSERT OR IGNORE INTO weap_65 SELECT DISTINCT lower(replace(j.value, ' ', ''))
  FROM content_packs p, json_each(p.data, '$.data.classes.skillGain.weaponSkills') w, json_each(w.value, '$.skills') j
  WHERE p.source = 'imported' AND j.type = 'text';
INSERT OR IGNORE INTO weap_65 SELECT DISTINCT lower(replace(j.value, ' ', ''))
  FROM content_rows r, json_each(r.data, '$.weaponSkills') w, json_each(w.value, '$.skills') j
  WHERE r.dataset = 'classes' AND r.part = 'skillGain' AND r.op = 'set' AND json_type(r.data, '$.weaponSkills') = 'array' AND j.type = 'text';
INSERT OR IGNORE INTO weap_65 SELECT DISTINCT lower(replace(j.value, ' ', ''))
  FROM content_draft r, json_each(r.data, '$.weaponSkills') w, json_each(w.value, '$.skills') j
  WHERE r.dataset = 'classes' AND r.part = 'skillGain' AND r.op = 'set' AND json_type(r.data, '$.weaponSkills') = 'array' AND j.type = 'text';

-- Every skill a harvest node names, in any layer (Classic's, the packs', the operator's, the draft).
CREATE TEMP TABLE harvest_65 (k TEXT PRIMARY KEY);
INSERT OR IGNORE INTO harvest_65 VALUES ('farming'), ('lumberjacking'), ('mining'), ('shoveling');
INSERT OR IGNORE INTO harvest_65 SELECT lower(replace(json_extract(h.value, '$.skill'), ' ', ''))
  FROM content_packs p, json_each(p.data, '$.data.gather.harvest') h WHERE p.source = 'imported' AND json_type(h.value, '$.skill') = 'text';
INSERT OR IGNORE INTO harvest_65 SELECT lower(replace(json_extract(h.value, '$.skill'), ' ', ''))
  FROM content_rows r, json_each(r.data) h WHERE r.dataset = 'gather' AND r.part = 'harvest' AND r.op = 'set' AND json_type(r.data) = 'array' AND json_type(h.value, '$.skill') = 'text';
INSERT OR IGNORE INTO harvest_65 SELECT lower(replace(json_extract(h.value, '$.skill'), ' ', ''))
  FROM content_draft r, json_each(r.data) h WHERE r.dataset = 'gather' AND r.part = 'harvest' AND r.op = 'set' AND json_type(r.data) = 'array' AND json_type(h.value, '$.skill') = 'text';

-- The gain rows and skill bindings in effect at each layer (cl_: Classic's own).
CREATE TEMP TABLE layer_65 (cl_g TEXT, cl_b TEXT, pack_g TEXT, pack_b TEXT, op_g TEXT, op_b TEXT, dr_g TEXT, dr_b TEXT);
INSERT INTO layer_65 (cl_g, cl_b, pack_g, pack_b)
SELECT c.gains, c.binds,
  coalesce((SELECT json_extract(data, '$.data.gather.skillGain') FROM content_packs
    WHERE source = 'imported' AND json_type(data, '$.data.gather.skillGain') = 'array'
    ORDER BY position DESC, id DESC LIMIT 1), c.gains),
  coalesce((SELECT json_extract(data, '$.data.bindings.skills') FROM content_packs
    WHERE source = 'imported' AND json_type(data, '$.data.bindings.skills') = 'object'
    ORDER BY position DESC, id DESC LIMIT 1), c.binds)
FROM classic_65 c;
UPDATE layer_65 SET
  op_g = coalesce((SELECT data FROM content_rows WHERE dataset = 'gather' AND part = 'skillGain' AND op = 'set' AND json_type(data) = 'array'), pack_g),
  op_b = coalesce((SELECT data FROM content_rows WHERE dataset = 'bindings' AND part = 'skills' AND op = 'set' AND json_type(data) = 'object'), pack_b);
UPDATE layer_65 SET
  dr_g = coalesce((SELECT CASE op WHEN 'revert' THEN pack_g ELSE data END FROM content_draft
    WHERE dataset = 'gather' AND part = 'skillGain' AND (op = 'revert' OR (op = 'set' AND json_type(data) = 'array'))), op_g),
  dr_b = coalesce((SELECT CASE op WHEN 'revert' THEN pack_b ELSE data END FROM content_draft
    WHERE dataset = 'bindings' AND part = 'skills' AND (op = 'revert' OR (op = 'set' AND json_type(data) = 'object'))), op_b);

-- Every skill the packs or the operator layer list, with the pack row it is based on (old shape),
-- and whether an imported pack lists it (then its migrated row reads the packs' gain rows and
-- bindings; else it is Classic's, which reads Classic's).
CREATE TEMP TABLE skills_65 (k TEXT PRIMARY KEY COLLATE NOCASE, base TEXT, in_pack INTEGER NOT NULL);
INSERT OR IGNORE INTO skills_65
SELECT json_extract(s.value, '$.skill'), s.value, 1 FROM content_packs p, json_each(p.data, '$.data.classes.skills') s
WHERE p.source = 'imported' AND json_type(s.value, '$.skill') = 'text' ORDER BY p.position DESC, p.id DESC;
INSERT OR IGNORE INTO skills_65 SELECT json_extract(s.value, '$.skill'), s.value, 0 FROM classic_65 c, json_each(c.skills) s;
INSERT OR IGNORE INTO skills_65 SELECT row_key, NULL, 0 FROM content_rows WHERE dataset = 'classes' AND part = 'skills' AND op = 'set';
-- The operator layer: a skill whose effective gain row or binding comes out differently from what
-- its migrated pack row says (the operator changed it, or a pack with no skills of its own did)
-- gets a row of its own.
INSERT INTO content_rows (dataset, part, row_key, op, data, base_hash, base_data, seq, updated_by, updated_at)
SELECT 'classes', 'skills', s.k, 'set', s.base, NULL, s.base,
  (SELECT coalesce(max(seq), 0) FROM content_rows) + row_number() OVER (ORDER BY s.k),
  coalesce((SELECT updated_by FROM content_rows WHERE (dataset = 'gather' AND part = 'skillGain') OR (dataset = 'bindings' AND part = 'skills') ORDER BY dataset DESC LIMIT 1), 'system'),
  coalesce((SELECT updated_at FROM content_rows WHERE (dataset = 'gather' AND part = 'skillGain') OR (dataset = 'bindings' AND part = 'skills') ORDER BY dataset DESC LIMIT 1), '2026-11-23T00:00:00.000Z')
FROM skills_65 s, layer_65 l
WHERE s.base IS NOT NULL AND json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.op_b, '$.block') = 'text' AND json_type(l.op_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) <> (CASE WHEN s.in_pack THEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.pack_b, '$.block') = 'text' AND json_type(l.pack_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) ELSE json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 0 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.cl_b, '$.block') = 'text' AND json_type(l.cl_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.cl_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) END)
  AND NOT EXISTS (SELECT 1 FROM content_rows r WHERE r.dataset = 'classes' AND r.part = 'skills' AND r.row_key = s.k COLLATE NOCASE);
-- The draft likewise, over the operator layer.
INSERT INTO content_draft (dataset, part, row_key, op, data, author_account_id, author, updated_at)
SELECT 'classes', 'skills', s.k, 'set',
  coalesce((SELECT data FROM content_rows r WHERE r.dataset = 'classes' AND r.part = 'skills' AND r.row_key = s.k COLLATE NOCASE AND r.op = 'set'), s.base),
  d.author_account_id, d.author, d.updated_at
FROM skills_65 s, layer_65 l,
  (SELECT author_account_id, author, updated_at FROM content_draft WHERE (dataset = 'gather' AND part = 'skillGain') OR (dataset = 'bindings' AND part = 'skills') ORDER BY dataset DESC LIMIT 1) d
WHERE coalesce((SELECT data FROM content_rows r WHERE r.dataset = 'classes' AND r.part = 'skills' AND r.row_key = s.k COLLATE NOCASE AND r.op = 'set'), s.base) IS NOT NULL
  AND json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.dr_b, '$.block') = 'text' AND json_type(l.dr_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.dr_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.dr_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) <> json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.op_b, '$.block') = 'text' AND json_type(l.op_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))
  AND NOT EXISTS (SELECT 1 FROM content_draft r WHERE r.dataset = 'classes' AND r.part = 'skills' AND r.row_key = s.k COLLATE NOCASE)
  AND NOT EXISTS (SELECT 1 FROM content_rows r WHERE r.dataset = 'classes' AND r.part = 'skills' AND r.row_key = s.k COLLATE NOCASE AND r.op = 'remove');

-- A draft revert of a skill row meant to drop the operator's change, not the gain rate the gain
-- rows still gave it: it becomes the pack row with that rate.
UPDATE content_draft SET op = 'set', data = (SELECT s.base FROM skills_65 s WHERE s.k = content_draft.row_key)
WHERE dataset = 'classes' AND part = 'skills' AND op = 'revert'
  AND EXISTS (SELECT 1 FROM skills_65 s, layer_65 l WHERE s.k = content_draft.row_key AND s.base IS NOT NULL
    AND json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.dr_b, '$.block') = 'text' AND json_type(l.dr_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.dr_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.dr_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.dr_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) <> (CASE WHEN s.in_pack THEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.pack_b, '$.block') = 'text' AND json_type(l.pack_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) ELSE json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 0 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.cl_b, '$.block') = 'text' AND json_type(l.cl_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.cl_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) END));

-- Skill rows take the progression of their layer (their bases, the packs').
UPDATE content_rows SET data = (SELECT CASE WHEN json_type(content_rows.data) <> 'object' OR json_type(content_rows.data, '$.progression') IS NOT NULL THEN content_rows.data WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(op_b, '$.block') = 'text' AND json_type(op_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN content_rows.data ELSE json_set(content_rows.data, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(op_b, '$.block') = 'text' AND json_type(op_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65)
WHERE dataset = 'classes' AND part = 'skills' AND op = 'set';
-- Removal markers too keep the pack row they were based on.
UPDATE content_rows SET
  base_data = CASE WHEN base_data IS NULL THEN NULL
    WHEN EXISTS (SELECT 1 FROM skills_65 s WHERE s.k = content_rows.row_key AND s.in_pack)
    THEN (SELECT CASE WHEN json_type(content_rows.base_data) <> 'object' OR json_type(content_rows.base_data, '$.progression') IS NOT NULL THEN content_rows.base_data WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(pack_b, '$.block') = 'text' AND json_type(pack_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN content_rows.base_data ELSE json_set(content_rows.base_data, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(pack_b, '$.block') = 'text' AND json_type(pack_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65)
    ELSE (SELECT CASE WHEN json_type(content_rows.base_data) <> 'object' OR json_type(content_rows.base_data, '$.progression') IS NOT NULL THEN content_rows.base_data WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', ''))), CASE WHEN 0 AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(cl_b, '$.block') = 'text' AND json_type(cl_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(cl_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN content_rows.base_data ELSE json_set(content_rows.base_data, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', ''))), CASE WHEN 0 AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(cl_b, '$.block') = 'text' AND json_type(cl_b, '$.parry') = 'text' AND lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(cl_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) = lower(replace(json_extract(cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_rows.base_data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65) END,
  base_hash = CASE WHEN base_data IS NULL THEN base_hash ELSE NULL END
WHERE dataset = 'classes' AND part = 'skills';
UPDATE content_draft SET data = (SELECT CASE WHEN json_type(content_draft.data) <> 'object' OR json_type(content_draft.data, '$.progression') IS NOT NULL THEN content_draft.data WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_draft.data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(dr_b, '$.block') = 'text' AND json_type(dr_b, '$.parry') = 'text' AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(dr_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(dr_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN content_draft.data ELSE json_set(content_draft.data, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(content_draft.data, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(dr_b, '$.block') = 'text' AND json_type(dr_b, '$.parry') = 'text' AND lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(dr_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) = lower(replace(json_extract(dr_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(dr_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(content_draft.data, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65)
WHERE dataset = 'classes' AND part = 'skills' AND op = 'set';

-- The gain rows go; the kill lists, skill books, spell schools and gathering texts change shape.
DELETE FROM content_rows WHERE dataset = 'gather' AND part = 'skillGain';
DELETE FROM content_draft WHERE dataset = 'gather' AND part = 'skillGain';
UPDATE content_rows SET data = CASE WHEN json_type(content_rows.data, '$.weaponSkills') = 'array' THEN json_set(content_rows.data, '$.weaponSkills', (SELECT json_group_array(json(CASE WHEN json_type(w.value, '$.skills') = 'array' THEN json_set(w.value, '$.skills', (SELECT json_group_array(x.value) FROM (SELECT j.value, j.key FROM json_each(w.value, '$.skills') j LEFT JOIN rules_65 r ON r.k = lower(replace(j.value, ' ', '')) ORDER BY coalesce(r.n, 99), j.key) x)) ELSE w.value END)) FROM (SELECT value FROM json_each(content_rows.data, '$.weaponSkills') ORDER BY key) w)) ELSE content_rows.data END WHERE dataset = 'classes' AND part = 'skillGain' AND op = 'set';
UPDATE content_rows SET data = CASE WHEN json_type(content_rows.data, '$.skillBooks') = 'array' THEN json_set(content_rows.data, '$.skillBooks', (SELECT json_group_array(json(CASE WHEN json_type(e.value) = 'object' AND json_type(e.value, '$.points') IS NULL THEN json_set(json_remove(e.value, '$.shown'), '$.points', json('[{"op":"set","value":"1 + random(5)"}]'), '$.upTo', 77) ELSE e.value END)) FROM (SELECT value FROM json_each(content_rows.data, '$.skillBooks') ORDER BY key) e)) ELSE content_rows.data END WHERE dataset = 'itemRules' AND part = 'use' AND op = 'set';
UPDATE content_rows SET data = CASE WHEN json_type(content_rows.data, '$.school.line') IS NOT NULL THEN json_remove(content_rows.data, '$.school.line') ELSE content_rows.data END WHERE dataset = 'spells' AND part = 'spells' AND op = 'set';
UPDATE content_rows SET data = CASE WHEN json_type(content_rows.data, '$.texts.advanced') IS NOT NULL THEN json_remove(content_rows.data, '$.texts.advanced') ELSE content_rows.data END WHERE dataset = 'gather' AND part = 'gathering' AND op = 'set';
UPDATE content_draft SET data = CASE WHEN json_type(content_draft.data, '$.weaponSkills') = 'array' THEN json_set(content_draft.data, '$.weaponSkills', (SELECT json_group_array(json(CASE WHEN json_type(w.value, '$.skills') = 'array' THEN json_set(w.value, '$.skills', (SELECT json_group_array(x.value) FROM (SELECT j.value, j.key FROM json_each(w.value, '$.skills') j LEFT JOIN rules_65 r ON r.k = lower(replace(j.value, ' ', '')) ORDER BY coalesce(r.n, 99), j.key) x)) ELSE w.value END)) FROM (SELECT value FROM json_each(content_draft.data, '$.weaponSkills') ORDER BY key) w)) ELSE content_draft.data END WHERE dataset = 'classes' AND part = 'skillGain' AND op = 'set';
UPDATE content_draft SET data = CASE WHEN json_type(content_draft.data, '$.skillBooks') = 'array' THEN json_set(content_draft.data, '$.skillBooks', (SELECT json_group_array(json(CASE WHEN json_type(e.value) = 'object' AND json_type(e.value, '$.points') IS NULL THEN json_set(json_remove(e.value, '$.shown'), '$.points', json('[{"op":"set","value":"1 + random(5)"}]'), '$.upTo', 77) ELSE e.value END)) FROM (SELECT value FROM json_each(content_draft.data, '$.skillBooks') ORDER BY key) e)) ELSE content_draft.data END WHERE dataset = 'itemRules' AND part = 'use' AND op = 'set';
UPDATE content_draft SET data = CASE WHEN json_type(content_draft.data, '$.school.line') IS NOT NULL THEN json_remove(content_draft.data, '$.school.line') ELSE content_draft.data END WHERE dataset = 'spells' AND part = 'spells' AND op = 'set';
UPDATE content_draft SET data = CASE WHEN json_type(content_draft.data, '$.texts.advanced') IS NOT NULL THEN json_remove(content_draft.data, '$.texts.advanced') ELSE content_draft.data END WHERE dataset = 'gather' AND part = 'gathering' AND op = 'set';
-- The pack rows operator rows (removal markers too) were based on take the same shape.
UPDATE content_rows SET base_data = CASE WHEN json_type(content_rows.base_data, '$.weaponSkills') = 'array' THEN json_set(content_rows.base_data, '$.weaponSkills', (SELECT json_group_array(json(CASE WHEN json_type(w.value, '$.skills') = 'array' THEN json_set(w.value, '$.skills', (SELECT json_group_array(x.value) FROM (SELECT j.value, j.key FROM json_each(w.value, '$.skills') j LEFT JOIN rules_65 r ON r.k = lower(replace(j.value, ' ', '')) ORDER BY coalesce(r.n, 99), j.key) x)) ELSE w.value END)) FROM (SELECT value FROM json_each(content_rows.base_data, '$.weaponSkills') ORDER BY key) w)) ELSE content_rows.base_data END, base_hash = NULL WHERE dataset = 'classes' AND part = 'skillGain' AND base_data IS NOT NULL;
UPDATE content_rows SET base_data = CASE WHEN json_type(content_rows.base_data, '$.skillBooks') = 'array' THEN json_set(content_rows.base_data, '$.skillBooks', (SELECT json_group_array(json(CASE WHEN json_type(e.value) = 'object' AND json_type(e.value, '$.points') IS NULL THEN json_set(json_remove(e.value, '$.shown'), '$.points', json('[{"op":"set","value":"1 + random(5)"}]'), '$.upTo', 77) ELSE e.value END)) FROM (SELECT value FROM json_each(content_rows.base_data, '$.skillBooks') ORDER BY key) e)) ELSE content_rows.base_data END, base_hash = NULL WHERE dataset = 'itemRules' AND part = 'use' AND base_data IS NOT NULL;
UPDATE content_rows SET base_data = CASE WHEN json_type(content_rows.base_data, '$.school.line') IS NOT NULL THEN json_remove(content_rows.base_data, '$.school.line') ELSE content_rows.base_data END, base_hash = NULL WHERE dataset = 'spells' AND part = 'spells' AND base_data IS NOT NULL;
UPDATE content_rows SET base_data = CASE WHEN json_type(content_rows.base_data, '$.texts.advanced') IS NOT NULL THEN json_remove(content_rows.base_data, '$.texts.advanced') ELSE content_rows.base_data END, base_hash = NULL WHERE dataset = 'gather' AND part = 'gathering' AND base_data IS NOT NULL;

-- The publish log: the same changes to the rows it keeps. Its gain rows go; a publish that changed
-- them gains, in their place, an entry for each skill whose progression they changed, so undoing it
-- still puts the old rate back (with the bindings of the operator layer).
UPDATE content_publishes
SET changes = (
  SELECT json_group_array(json(e.v)) FROM (
    SELECT c.key AS ord, 0 AS sub, '' AS k, CASE
    WHEN json_extract(c.value, '$.dataset') = 'classes' AND json_extract(c.value, '$.part') = 'skills' THEN json_set(c.value, '$.before', json(CASE WHEN json_type(c.value, '$.before') <> 'object' OR json_type(c.value, '$.before') IS NULL THEN json_extract(c.value, '$.before') WHEN json_type(c.value, '$.before.baseData') IN ('object', 'array') THEN json_set(CASE WHEN json_type(c.value, '$.before.data') IN ('object', 'array') THEN json_set(json_extract(c.value, '$.before'), '$.data', json((SELECT CASE WHEN json_type(json_extract(c.value, '$.before.data')) <> 'object' OR json_type(json_extract(c.value, '$.before.data'), '$.progression') IS NOT NULL THEN json_extract(c.value, '$.before.data') WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(op_b, '$.block') = 'text' AND json_type(op_b, '$.parry') = 'text' AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN json_extract(c.value, '$.before.data') ELSE json_set(json_extract(c.value, '$.before.data'), '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(op_b, '$.block') = 'text' AND json_type(op_b, '$.parry') = 'text' AND lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) = lower(replace(json_extract(op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(op_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(json_extract(c.value, '$.before.data'), '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65))) ELSE json_extract(c.value, '$.before') END, '$.baseData', json((SELECT CASE WHEN EXISTS (SELECT 1 FROM skills_65 s WHERE s.k = json_extract(c.value, '$.key') AND s.in_pack) THEN CASE WHEN json_type(json_extract(c.value, '$.before.baseData')) <> 'object' OR json_type(json_extract(c.value, '$.before.baseData'), '$.progression') IS NOT NULL THEN json_extract(c.value, '$.before.baseData') WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(pack_b, '$.block') = 'text' AND json_type(pack_b, '$.parry') = 'text' AND lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(json_extract(c.value, '$.before.baseData'), '$.skill'), ' ', '')) = lower(replace(json