s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(s.base, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(s.base, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN s.base ELSE json_set(s.base, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(s.base, '$.skill'), ' ', ''))), CASE WHEN 0 AND lower(replace(json_extract(s.base, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(s.base, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.cl_b, '$.block') = 'text' AND json_type(l.cl_b, '$.parry') = 'text' AND lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.cl_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(s.base, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(s.base, '$.skill'), ' ', '')) = lower(replace(json_extract(l.cl_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(l.cl_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(s.base, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END END)))))
    FROM json_each(content_publishes.changes) c, skills_65 s, layer_65 l
    WHERE json_extract(c.value, '$.dataset') = 'gather' AND json_extract(c.value, '$.part') = 'skillGain'
      AND s.base IS NOT NULL AND json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.op_b, '$.block') = 'text' AND json_type(l.op_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each((CASE WHEN json_type(c.value, '$.before.data') = 'array' THEN json_extract(c.value, '$.before.data') ELSE l.pack_g END)) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) <> json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(s.k, ' ', ''))), CASE WHEN 1 AND lower(replace(s.k, ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(s.k, ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(l.op_b, '$.block') = 'text' AND json_type(l.op_b, '$.parry') = 'text' AND lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(l.op_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.cooking'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.blacksmithing'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.alchemy'), ' ', '')) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(s.k, ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(s.k, ' ', '')) = lower(replace(json_extract(l.op_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each((CASE WHEN json_type(c.value, '$.after.data') = 'array' THEN json_extract(c.value, '$.after.data') ELSE l.pack_g END)) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(s.k, ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))
    ORDER BY 1, 2, 3
  ) e
)
WHERE EXISTS (
  SELECT 1 FROM json_each(content_publishes.changes) c
  WHERE json_extract(c.value, '$.dataset') IN ('classes', 'itemRules', 'spells', 'gather')
);

-- Imported packs: skills take the progression the packs imply, classes the world defaults, and the
-- other datasets change shape. A pack's datasets are whole.
UPDATE content_packs SET data = json_set(data, '$.data.classes.skills', (
  SELECT json_group_array(json((SELECT CASE WHEN json_type(s.value) <> 'object' OR json_type(s.value, '$.progression') IS NOT NULL THEN s.value WHEN json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(s.value, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(pack_b, '$.block') = 'text' AND json_type(pack_b, '$.parry') = 'text' AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(s.value, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(s.value, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}')) = '{}' THEN s.value ELSE json_set(s.value, '$.progression', json_object('model', 'chance', 'on', json(json_patch(json_patch(coalesce((SELECT json_object('kill', json(s)) FROM kill_65 WHERE k = lower(replace(json_extract(s.value, '$.skill'), ' ', ''))), CASE WHEN 1 AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) IN (SELECT k FROM weap_65) AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) NOT IN (SELECT k FROM rules_65) THEN json_object('kill', json('false')) ELSE '{}' END), CASE WHEN json_type(pack_b, '$.block') = 'text' AND json_type(pack_b, '$.parry') = 'text' AND lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.block'), ' ', '')) THEN json_object('defend', json_object('requires', json_object('skill', json_extract(pack_b, '$.parry'), 'above', 50))) ELSE '{}' END), coalesce((SELECT CASE WHEN lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.cooking'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.blacksmithing'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.alchemy'), ' ', '')) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.carpentry'), ' ', '')) THEN CASE WHEN (lower(replace(json_extract(s.value, '$.skill'), ' ', '')) IN (SELECT k FROM harvest_65) OR lower(replace(json_extract(s.value, '$.skill'), ' ', '')) = lower(replace(json_extract(pack_b, '$.fishing'), ' ', ''))) THEN json_object('gather', json(x.s), 'craft', json(x.s)) ELSE json_object('craft', json(x.s)) END ELSE json_object('gather', json(x.s)) END FROM (SELECT (SELECT json_patch(json_object('roll', json_extract(g.value, '$.chance'), 'cap', min(100, max(0, json_extract(g.value, '$.below')))), CASE WHEN coalesce(json_extract(g.value, '$.min'), 0) > 0 THEN json_object('min', min(100, json_extract(g.value, '$.min'))) ELSE '{}' END) FROM json_each(pack_g) g WHERE lower(replace(json_extract(g.value, '$.skill'), ' ', '')) = lower(replace(json_extract(s.value, '$.skill'), ' ', '')) ORDER BY g.key LIMIT 1) AS s) x WHERE x.s IS NOT NULL), '{}'))))) END FROM layer_65)))
  FROM (SELECT value FROM json_each(content_packs.data, '$.data.classes.skills') ORDER BY key) s))
WHERE source = 'imported' AND json_type(data, '$.data.classes.skills') = 'array';
UPDATE content_packs SET data = json_set(data, '$.data.classes.progression', json((SELECT prog FROM classic_65)))
WHERE source = 'imported' AND json_type(data, '$.data.classes') = 'object' AND json_type(data, '$.data.classes.progression') IS NULL;
UPDATE content_packs SET data = json_set(data, '$.data.classes.skillGain', json(CASE WHEN json_type(json_extract(data, '$.data.classes.skillGain'), '$.weaponSkills') = 'array' THEN json_set(json_extract(data, '$.data.classes.skillGain'), '$.weaponSkills', (SELECT json_group_array(json(CASE WHEN json_type(w.value, '$.skills') = 'array' THEN json_set(w.value, '$.skills', (SELECT json_group_array(x.value) FROM (SELECT j.value, j.key FROM json_each(w.value, '$.skills') j LEFT JOIN rules_65 r ON r.k = lower(replace(j.value, ' ', '')) ORDER BY coalesce(r.n, 99), j.key) x)) ELSE w.value END)) FROM (SELECT value FROM json_each(json_extract(data, '$.data.classes.skillGain'), '$.weaponSkills') ORDER BY key) w)) ELSE json_extract(data, '$.data.classes.skillGain') END))
WHERE source = 'imported' AND json_type(data, '$.data.classes.skillGain') = 'object';
UPDATE content_packs SET data = json_set(data, '$.data."item-rules".use', json(CASE WHEN json_type(json_extract(data, '$.data."item-rules".use'), '$.skillBooks') = 'array' THEN json_set(json_extract(data, '$.data."item-rules".use'), '$.skillBooks', (SELECT json_group_array(json(CASE WHEN json_type(e.value) = 'object' AND json_type(e.value, '$.points') IS NULL THEN json_set(json_remove(e.value, '$.shown'), '$.points', json('[{"op":"set","value":"1 + random(5)"}]'), '$.upTo', 77) ELSE e.value END)) FROM (SELECT value FROM json_each(json_extract(data, '$.data."item-rules".use'), '$.skillBooks') ORDER BY key) e)) ELSE json_extract(data, '$.data."item-rules".use') END))
WHERE source = 'imported' AND json_type(data, '$.data."item-rules".use') = 'object';
UPDATE content_packs SET data = json_set(data, '$.data.spells.spells', (
  SELECT json_group_array(json(CASE WHEN json_type(s.value, '$.school.line') IS NOT NULL THEN json_remove(s.value, '$.school.line') ELSE s.value END))
  FROM (SELECT value FROM json_each(content_packs.data, '$.data.spells.spells') ORDER BY key) s))
WHERE source = 'imported' AND json_type(data, '$.data.spells.spells') = 'array';
UPDATE content_packs SET data = json_remove(data, '$.data.gather.skillGain', '$.data.gather.gathering.texts.advanced')
WHERE source = 'imported' AND json_type(data, '$.data.gather') = 'object';

DROP TABLE classic_65;
DROP TABLE kill_65;
DROP TABLE rules_65;
DROP TABLE layer_65;
DROP TABLE skills_65;
DROP TABLE harvest_65;
DROP TABLE weap_65;
